CREATE TABLE IF NOT EXISTS schema_versions (version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS assets (asset_id TEXT PRIMARY KEY, symbol TEXT NOT NULL, issuer_id TEXT, asset_type TEXT NOT NULL, watchlist_tier TEXT NOT NULL, configuration TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources (source_id TEXT PRIMARY KEY, url TEXT NOT NULL, module TEXT NOT NULL, access_policy TEXT NOT NULL, parser_version TEXT NOT NULL, health TEXT NOT NULL DEFAULT 'unseen', last_attempt TEXT, last_success TEXT, last_error TEXT, cursor TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS documents (document_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources, external_id TEXT NOT NULL, canonical_url TEXT NOT NULL, published_at TEXT, first_seen_at TEXT NOT NULL, event_at TEXT NOT NULL, content_hash TEXT NOT NULL, version INTEGER NOT NULL, payload TEXT NOT NULL, UNIQUE(source_id, external_id, version));
CREATE INDEX IF NOT EXISTS documents_url ON documents(canonical_url);
CREATE TABLE IF NOT EXISTS events (event_key TEXT PRIMARY KEY, module TEXT NOT NULL, kind TEXT NOT NULL, event_at TEXT NOT NULL, published_at TEXT, first_seen_at TEXT NOT NULL, updated_at TEXT NOT NULL, scheduled_at TEXT, status TEXT NOT NULL, title TEXT NOT NULL, summary TEXT NOT NULL, importance DOUBLE PRECISION NOT NULL, metadata TEXT NOT NULL, version INTEGER NOT NULL, current_document TEXT NOT NULL REFERENCES documents, attempts INTEGER NOT NULL DEFAULT 0, next_check TEXT);
CREATE INDEX IF NOT EXISTS events_due ON events(next_check);
CREATE INDEX IF NOT EXISTS events_updated ON events(updated_at);
CREATE TABLE IF NOT EXISTS event_documents (event_key TEXT NOT NULL REFERENCES events, document_id TEXT NOT NULL REFERENCES documents, PRIMARY KEY(event_key, document_id));
CREATE TABLE IF NOT EXISTS facts (document_id TEXT NOT NULL REFERENCES documents, ordinal INTEGER NOT NULL, event_key TEXT NOT NULL REFERENCES events, metric TEXT NOT NULL, value TEXT, unit TEXT, period TEXT, vintage TEXT, PRIMARY KEY(document_id, ordinal));
CREATE TABLE IF NOT EXISTS signals (event_key TEXT NOT NULL REFERENCES events, asset_id TEXT NOT NULL, one_liner TEXT NOT NULL, importance DOUBLE PRECISION NOT NULL, direction DOUBLE PRECISION, confidence DOUBLE PRECISION, horizon TEXT NOT NULL, evidence_urls TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL, PRIMARY KEY(event_key, asset_id));
CREATE TABLE IF NOT EXISTS jobs (job_name TEXT PRIMARY KEY, last_run TEXT, last_success TEXT, last_error TEXT, retry_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS slots (job_name TEXT NOT NULL, slot TEXT NOT NULL, PRIMARY KEY(job_name,slot));
CREATE TABLE IF NOT EXISTS reports (report_id TEXT PRIMARY KEY, filename TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, mail_state TEXT NOT NULL DEFAULT 'disabled', mail_error TEXT);
CREATE TABLE IF NOT EXISTS model_cache (cache_key TEXT PRIMARY KEY, result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS spend (call_id TEXT PRIMARY KEY, job TEXT NOT NULL, model TEXT NOT NULL, day TEXT NOT NULL, estimate BIGINT NOT NULL, charged BIGINT NOT NULL, input_tokens INTEGER, output_tokens INTEGER, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analysis_queue (event_key TEXT NOT NULL, asset_id TEXT NOT NULL, version INTEGER NOT NULL, attempts INTEGER NOT NULL, retry_at TEXT NOT NULL, PRIMARY KEY(event_key,asset_id,version));
CREATE TABLE IF NOT EXISTS alert_queue (alert_id TEXT PRIMARY KEY, event_key TEXT NOT NULL REFERENCES events, event_version INTEGER NOT NULL, event_data TEXT NOT NULL, created_at TEXT NOT NULL, report_id TEXT REFERENCES reports);
CREATE TABLE IF NOT EXISTS file_deliveries (report_id TEXT PRIMARY KEY REFERENCES reports, written_at TEXT NOT NULL);
